dtsPropsFor.Chevron:
/** Which way the arrow points. */
dir?: "left" | "right";
/** Utility classes. Size it and colour it — the stroke is `currentColor`. */
className?: string;

dtsPropsFor.VerseFlow:
/** The verses to set, in order. Verse 1 renders as a rubricated drop initial. */
verses: { verse: number; text: string }[];
/** Chapter number — this is what the drop initial shows. */
chapter: number;

dtsPropsFor.PageFace:
/** Which half of the spread this leaf is. Sets the gutter margin and which
 *  side of the running head carries the book name. */
side: "verso" | "recto";
/** Book name, for the running head. */
book: string;
/** Chapter number — drives the drop initial and the printed verse range. */
chapter: number;
/** Verses for this leaf. Pass an empty array for a blank leaf: the running
 *  head and folio are hidden with `invisible`, never removed. */
verses: { verse: number; text: string }[];
/** Page number, printed in the footer. */
folio: number;
/** Ref to the body column. The paginator measures this element. */
bodyRef?: React.Ref<HTMLDivElement>;

dtsPropsFor.Contents:
/** Index into CANON of the book currently open. It gets the marker and initial focus. */
current: number;
/** Called with the CANON index of the book the reader picked. */
onPick: (index: number) => void;
/** Called on Escape, or on a click outside the panel. */
onClose: () => void;
